ok($approvedAct['code']===302 && str_contains(http('page=acts')['body'],'Revisado por Nómina QA'),'Aprobación de acto por HTTP conserva y muestra responsable y fecha');
$csrf=login('qa14');
$nightPost=['action'=>'submit','csrf'=>$csrf,'category_id'=>'2','justification'=>'Solicitud nocturna de prueba por formulario HTTP','special_note'=>'Mi turno de domingo a lunes incluye un descanso de treinta minutos','slots[0][date]'=>'2026-12-13','slots[0][mode]'=>'full','slots[0][special]'=>'1','slots[0][periods][0][start]'=>'22:00','slots[0][periods][0][start_day]'=>'0','slots[0][periods][0][end]'=>'02:00','slots[0][periods][0][end_day]'=>'1','slots[0][periods][1][start]'=>'02:30','slots[0][periods][1][start_day]'=>'1','slots[0][periods][1][end]'=>'06:30','slots[0][periods][1][end_day]'=>'1','supports[0]'=>new CURLFile($root.'/.work/soporte.pdf','application/pdf','turno.pdf')];
$nightResponse=http('page=new',$nightPost,true);
