ok(str_contains($nightDetail,'2026-12-14 06:30:00') && str_contains($nightDetail,'8 h 00 min') && str_contains($nightDetail,'Jornada especial declarada'),'El detalle muestra el día siguiente, descanso excluido y horario declarado');
