$estimate=http('page=estimate&'.http_build_query(['slot'=>['special'=>1,'date'=>'2026-12-13','mode'=>'full','periods'=>[['start'=>'22:00','start_day'=>0,'end'=>'02:00','end_day'=>1],['start'=>'02:30','start_day'=>1,'end'=>'06:30','end_day'=>1]]]]));
